parts.text:
{
  "ui_japanese": "こんにちは！元気ですか？",
  "ui_romaji": "Konnichiwa! Genki desu ka?",
  "ui_english": "Hello! How are you?",
  "spoken_payload": "こんにちは！元気ですか？ Konnichiwa! Genki desu ka?",
  "new_vocabulary": [
    {
      "japanese": "元気",
      "romaji": "genki",
      "english": "healthy/fine"
    }
  ]
}

{
  "ui_japanese": "こんにちは！今日はいい天気ですね。",
  "ui_romaji": "Konnichiwa! Kyou wa ii tenki desu ne.",
  "ui_english": "Hello! The weather is nice today, isn't it?",
  "spoken_payload": "こんにちは！今日はいい天気ですね。 Konnichiwa! Kyou wa ii tenki desu ne.",
  "new_vocabulary": [
    {
      "japanese": "天気",
      "romaji": "tenki",
      "english": "weather"
    }
  ]
}

{
  "ui_japanese": "こんにちは！一緒に日本語を勉強しましょう。",
  "ui_romaji": "Konnichiwa! Issho ni nihongo o benkyou shimashou.",
  "ui_english": "Hello! Let's study Japanese together.",
  "spoken_payload": "こんにちは！一緒に日本語を勉強しましょう。 Konnichiwa! Issho ni nihongo o benkyou shimashou.",
  "new_vocabulary": [
    {
      "japanese": "勉強",
      "romaji": "benkyou",
      "english": "study"
    }
  ]
}

{
  "ui_japanese": "ありがとうございます。袋はいりますか？150円です。",
  "ui_romaji": "Arigatou gozaimasu. Fukuro wa irimasu ka? Hyakugojuu-en desu.",
  "ui_english": "Thank you. Do you need a bag? That will be 150 yen.",
  "spoken_payload": "ありがとうございます。袋はいりますか？150円です。 Arigatou gozaimasu. Fukuro wa irimasu ka? Hyakugojuu-en desu.",
  "new_vocabulary": [
    {
      "japanese": "袋",
      "romaji": "fukuro",
      "english": "bag"
    }
  ]
}

{
  "ui_japanese": "「ジュースをください」と言いましょう。りんごジュースが好きですか？",
  "ui_romaji": "\"Juusu o kudasai\" to iimashou. Ringo juusu ga suki desu ka?",
  "ui_english": "Let's say \"Please give me a juice.\" Do you like apple juice?",
  "spoken_payload": "「ジュースをください」と言いましょう。りんごジュースが好きですか？ \"Juusu o kudasai\" to iimashou. Ringo juusu ga suki desu ka?",
  "new_vocabulary": [
    {
      "japanese": "ください",
      "romaji": "kudasai",
      "english": "please give me"
    }
  ]
}
